import { callTool, listTools } from "./server.mjs";

const checks = [];
function ok(label, cond) { checks.push([label, !!cond]); }

// tool listing + strict schema
const tools = await listTools();
ok("single tool", tools.length === 1 && tools[0].name === "order_status");
const sch = tools[0].inputSchema;
ok("additionalProperties false", sch.additionalProperties === false);
ok("required order_id", Array.isArray(sch.required) && sch.required[0] === "order_id");
ok("order_id is string", sch.properties.order_id.type === "string");
ok("include_history boolean", sch.properties.include_history.type === "boolean");

// default: status only, no history
const r1 = await callTool("order_status", { order_id: "o1" });
ok("status shipped", /shipped/.test(r1.content[0].text));
ok("no history by default", !/created\s*->\s*paid/.test(r1.content[0].text));

// include history -> chronological
const r2 = await callTool("order_status", { order_id: "o1", include_history: true });
ok("history created->paid->shipped", /created\s*->\s*paid\s*->\s*shipped/.test(r2.content[0].text));

// missing order_id
let err = null; try { await callTool("order_status", {}); } catch(e){ err = e; }
ok("missing order_id throws", err && /order_id/i.test(err.message));

// missing order
err = null; try { await callTool("order_status", { order_id: "nope" }); } catch(e){ err = e; }
ok("missing order throws", err && /not found/i.test(err.message));

// extra field
err = null; try { await callTool("order_status", { order_id: "o1", foo: 1 }); } catch(e){ err = e; }
ok("extra field throws", err && /Unexpected argument/i.test(err.message));

// wrong type for include_history
err = null; try { await callTool("order_status", { order_id: "o1", include_history: "yes" }); } catch(e){ err = e; }
ok("non-boolean include_history throws", err && /include_history/i.test(err.message));

// unknown tool
err = null; try { await callTool("frobnicate", {}); } catch(e){ err = e; }
ok("unknown tool throws", err && /Unknown tool/i.test(err.message));

let pass = 0, fail = 0;
for (const [l,c] of checks) { if (c) pass++; else { fail++; console.log("FAIL:", l); } }
console.log(`\\nPASS ${pass} / FAIL ${fail}`);
if (fail) process.exit(1);
'"}

